def compute_loss(outputs: dict[str, torch.Tensor], batch: dict[str, torch.Tensor], *, graph_pos_weight: torch.Tensor, role_pos_weights: dict[str, torch.Tensor]) -> tuple[torch.Tensor, dict[str, torch.Tensor]]:
    active = batch['y_attack'] >= 0.5
    count_targets = torch.full(batch['y_attacker_count'].shape, fill_value=-100, dtype=torch.int64, device=batch['y_attacker_count'].device)
    for raw_count, class_index in COUNT_CLASS_MAPPING.items():
        selector = active & (batch['y_attacker_count'] == raw_count)
        count_targets[selector] = class_index
    if bool((count_targets[active] < 0).any().item()):
        raise RuntimeError('one or more active count labels are outside 1..4')
    attack_loss = F.binary_cross_entropy_with_logits(outputs['attack_logits'], batch['y_attack'].float(), pos_weight=graph_pos_weight)
    if bool(active.any().item()):
        count_loss = F.cross_entropy(outputs['count_logits'][active], count_targets[active])
    else:
        count_loss = outputs['count_logits'].sum() * 0.0
    source_loss = F.binary_cross_entropy_with_logits(outputs['source_logits'], batch['y_source'].float(), pos_weight=role_pos_weights['source'])
    transit_loss = F.binary_cross_entropy_with_logits(outputs['transit_logits'], batch['y_transit'].float(), pos_weight=role_pos_weights['transit'])
    victim_loss = F.binary_cross_entropy_with_logits(outputs['victim_logits'], batch['y_victim'].float(), pos_weight=role_pos_weights['victim'])
    path_loss = F.binary_cross_entropy_with_logits(outputs['path_logits'], batch['y_attack_path'].float(), pos_weight=role_pos_weights['path'])
    components = {'attack': attack_loss, 'count': count_loss, 'source': source_loss, 'transit': transit_loss, 'victim': victim_loss, 'path': path_loss}
    total = sum((LOSS_WEIGHTS[key] * value for key, value in components.items()))
    return (total, components)

